<script setup>
import {computed} from 'vue';
import {fdate} from '../../lib/client-info';
import {loadClientConversions} from '../../lib/client-profile-sections';
import {useClientSectionData} from '../../composables/useClientSectionData';
import ClientConversionFields from './ClientConversionFields.vue';
const props=defineProps({bundle:Object});const {data,loading,error,warnings,load}=useClientSectionData(()=>props.bundle,'allConversions',loadClientConversions);
const groups=computed(()=>['B2B','C2C','P2P'].map(kind=>({kind,title:{B2B:'B to B',C2C:'C to C',P2P:'P to P'}[kind],rows:(data.value?.records||[]).filter(x=>x.kind===kind)})).filter(g=>g.rows.length));
function sections(doc){const groups=[['Transfer details',/^(conversion_status|date|branch|branch_name|receiving_branch|transfer_type|started_date)$/],['Clients & contact',/client|patient|name1|gender|mobile|phone/],['Package & payment',/invoice|amount|balance|charge|paid|session|package|stores/]],used=new Set(['name','creation']),out=[];for(const [title,re] of groups){const fields=Object.fromEntries(Object.entries(doc).filter(([k,v])=>!used.has(k)&&re.test(k)&&!Array.isArray(v)&&String(v).length<180&&!/^t\d|important|signature/.test(k)));Object.keys(fields).forEach(k=>used.add(k));if(Object.keys(fields).length)out.push({title,fields});}return {groups:out,tables:Object.entries(doc).filter(([k,v])=>!used.has(k)&&Array.isArray(v)&&v.length),rest:Object.fromEntries(Object.entries(doc).filter(([k,v])=>!used.has(k)&&!Array.isArray(v)))};}
</script>
<template><div class="c3-tab-body"><p v-if="loading" role="status">Loading conversions…</p><p v-if="error" role="alert">{{error}} <button class="c3-btn" @click="load(true)">Retry</button></p><p v-for="w in warnings" :key="w" role="alert">{{w}}</p><button v-if="warnings.length" class="c3-btn" @click="load(true)">Retry unavailable sources</button><template v-if="data"><div v-if="!groups.length" class="c3-center c3-empty"><div class="c3-state-ic">🔄</div><h3>No linked conversions or branch transfers</h3><p>No accessible requests match this client ID.</p></div><template v-for="group in groups" :key="group.kind"><h3 class="c3-conversion-heading">{{group.title}} · {{group.rows.length}}</h3><article v-for="x in group.rows" :key="x.doctype+x.doc.name" class="c3-conversion-summary"><header><b>{{x.doc.name}}</b><span>{{fdate(x.doc.creation||x.doc.date)}}</span><strong>{{x.doc.approval_display_status||x.doc.final_approval_status||x.doc.conversion_status||x.doc.approval_stage||x.doc.workflow_state||'Status not recorded'}}</strong></header><section v-for="s in sections(x.doc).groups" :key="s.title" class="c3-conversion-group"><h4>{{s.title}}</h4><ClientConversionFields :doc="s.fields"/></section><details v-for="[key,rows] in sections(x.doc).tables" :key="key" class="c3-conversion-more"><summary>{{key.replace(/_/g,' ')}} · {{rows.length}} records</summary><ClientConversionFields :doc="{[key]:rows}"/></details><details class="c3-conversion-more"><summary>Remarks, terms & supporting details</summary><ClientConversionFields :doc="sections(x.doc).rest"/></details></article></template></template></div></template>
